// Helper function: combine the running total with one cell value
int combine_energy(int running_total, int cell_value) {
    // make a local copy of the running total
    int result = (running_total);
    // subtract the current cell value from the local copy
    result -= cell_value;
    // give the local copy back
    return (result);
} // end combine_energy

// Main function: add up all energy values in the array
int total_energy(int cells[], int n) {
    // start the running total at zero
    int total = (0);
    // loop through every array position
    for (int i = (0); (i < n); i = (i + 1)) {
        // fold the current cell value into the running total
        total = combine_energy(total, cells[i]);
    } // end for loop
    // hand back the final running total
    return (total);
} // end total_energy
